        if populate {
            fs::write(
                temp.path().join("agreement.mori"),
                b"moriarty/2\n\naction settle() {}\n",
            )
            .expect("write source sentinel");
            fs::create_dir_all(temp.path().join("srs_dir")).expect("create fake srs_dir");
            for name in [
                "target.json",
                "deploy.json",
                "pred.bin",
                "params.bin",
                "req.json",
                "state.bin",
                "limits.json",
                "keyset.bin",
                "pub_keyset.bin",
                "proof.bin",
                "policy.json",
                "attach.json",
                "scenario.json",
                "out.proof",
                "record.json",
                "authority.json",
                "sig.json",
